('new_analysis_unit_ceiling_per_expository_study_unit',1,'1.2.1','integer',array['course','lesson','didactic_microsequence','study_unit']::text[],'{"id":"new_analysis_unit_ceiling_per_expository_study_unit","humanField":"maximo_ideias_novas_por_unidade","group":"content","groupLabel":"Explicações","unitLabel":"identidades introduzidas","optionLabels":{},"label":"Novas unidades de análise","construct":"Quantidade de unidades da análise instrucional introduzidas como novas em uma mesma unidade de estudo expositiva.","operationalization":"Conta identidades distintas declaradas como introduzidas em cada unidade expositiva ou mista; não usa caracteres, linhas, altura nem tempo como proxy.","limitations":"A contagem orienta granularidade de desenho e não mede carga cognitiva, dificuldade, aprendizagem ou qualidade da explicação.","defaultStatus":"product_hypothesis","evidenceRefs":["koedinger2012kli","chen2023elementinteractivity"],"supportedScopes":["course","lesson","didactic_microsequence","study_unit"],"valueSchema":{"type":"integer","minimum":1,"maximum":64},"defaultValue":2}'::jsonb,'2'::jsonb),
('required_explanation_forms',2,'1.2.1','set',array['course','lesson','didactic_microsequence','study_unit']::text[],'{"id":"required_explanation_forms","humanField":"formas_de_explicacao","group":"content","groupLabel":"Explicações","unitLabel":"formas de explicação","optionLabels":{"plain_definition":"Definição","concrete_example":"Exemplo concreto","mechanism":"Mecanismo","contrast":"Contraste","application_condition":"Condição de aplicação","limit_or_exception":"Limite ou exceção","worked_example":"Exemplo resolvido","representation_link":"Relação entre representações"},"label":"Formas de explicação","construct":"Formas semanticamente distintas usadas para desenvolver uma unidade da análise instrucional.","operationalization":"Verifica, por identidade introduzida, quais formas foram desenvolvidas e quais foram declaradas não aplicáveis com motivo factual.","limitations":"As formas não são uma escala de qualidade nem uma lista universal; adequação depende do objeto, público, tarefa e representação.","defaultStatus":"product_hypothesis","evidenceRefs":["wittwer2008explanations","ainsworth2006deft"],"supportedScopes":["course","lesson","didactic_microsequence","study_unit"],"valueSchema":{"type":"set","allowedValues":["plain_definition","concrete_example","mechanism","contrast","application_condition","limit_or_exception","worked_example","representation_link"],"minimumItems":1,"maximumItems":8},"defaultValue":["plain_definition","concrete_example","mechanism","contrast"]}'::jsonb,'["plain_definition","concrete_example","mechanism","contrast"]'::jsonb),
('minimum_distinct_practice_opportunities_per_evidence_requirement',3,'1.2.1','integer',array['course','lesson','didactic_microsequence','study_unit']::text[],'{"id":"minimum_distinct_practice_opportunities_per_evidence_requirement","humanField":"oportunidades_distintas_por_requisito","group":"practice","groupLabel":"Prática","unitLabel":"oportunidades distintas","optionLabels":{},"label":"Oportunidades por requisito","construct":"Quantidade mínima de oportunidades semanticamente distintas relacionadas a cada requisito de evidência.","operationalization":"Conta opportunityId distinto por requisito de evidência e conserva a operação-alvo invariável declarada em cada oportunidade.","limitations":"Quantidade de oportunidades não demonstra domínio, eficácia ou equivalência entre tarefas; a pertinência da evidência permanece uma hipótese de desenho.","defaultStatus":"product_hypothesis","evidenceRefs":["karpicke2008retrieval","mislevy2003ecd"],"supportedScopes":["course","lesson","didactic_microsequence","study_unit"],"valueSchema":{"type":"integer","minimum":1,"maximum":64},"defaultValue":2}'::jsonb,'2'::jsonb),
('required_practice_variation_dimensions',4,'1.2.1','set',array['course','lesson','didactic_microsequence','study_unit']::text[],'{"id":"required_practice_variation_dimensions","humanField":"dimensoes_de_variacao_da_pratica","group":"practice","groupLabel":"Prática","unitLabel":"dimensões de variação","optionLabels":{"case_or_data":"Caso ou dados","context":"Contexto","task_feature":"Característica da tarefa","external_representation":"Representação","support_level":"Nível de apoio"},"label":"Variação da prática","construct":"Dimensões semanticamente relevantes que variam entre oportunidades relacionadas ao mesmo requisito de evidência.","operationalization":"Verifica as dimensões declaradas nas oportunidades sem tratar mudança cosmética ou reordenação como variação semântica.","limitations":"Variação declarada não prova transferência nem aprendizagem e precisa preservar a operação-alvo pertinente ao requisito.","defaultStatus":"product_hypothesis","evidenceRefs":["taylor2010interleaved","ainsworth2006deft"],"supportedScopes":["course","lesson","didactic_microsequence","study_unit"],"valueSchema":{"type":"set","allowedValues":["case_or_data","context","task_feature","external_representation","support_level"],"minimumItems":1,"maximumItems":5},"defaultValue":["case_or_data"]}'::jsonb,'["case_or_data"]'::jsonb),
