('study_unit_content_word_target',6,'1.2.1','integer',array['course','lesson','didactic_microsequence','study_unit']::text[],'{"id":"study_unit_content_word_target","humanField":"alvo_palavras_unidade","group":"editorial","groupLabel":"Leitura e estilo","unitLabel":"palavras por unidade","optionLabels":{},"label":"Extensão das unidades","construct":"Extensão editorial pretendida para o conteúdo de uma unidade de estudo focal.","operationalization":"Orienta a distribuição do conteúdo em torno de um alvo flexível, depois de satisfeitas a função didática e as dependências necessárias.","limitations":"O alvo não é máximo, não mede qualidade ou carga cognitiva e não justifica compactação nem atomização.","defaultStatus":"product_hypothesis","evidenceRefs":[],"supportedScopes":["course","lesson","didactic_microsequence","study_unit"],"valueSchema":{"type":"integer","minimum":40,"maximum":1000},"defaultValue":180}'::jsonb,'180'::jsonb),
('practice_distribution',7,'1.2.1','enum',array['course','lesson','didactic_microsequence','study_unit']::text[],'{"id":"practice_distribution","humanField":"distribuicao_da_pratica","group":"practice","groupLabel":"Prática","unitLabel":"organização da sequência","label":"Distribuição das práticas","construct":"Organização das oportunidades de prática entre as exposições.","operationalization":"Observa posições e intervalos das unidades declaradas expositivas, práticas ou mistas; intercalar prefere prática entre exposições e agrupar prefere blocos.","limitations":"A distribuição é contextual; uma sequência curta ou mista não permite certificar alternância nem qualidade por contagem.","defaultStatus":"product_hypothesis","evidenceRefs":[],"supportedScopes":["course","lesson","didactic_microsequence","study_unit"],"valueSchema":{"type":"enum","allowedValues":["interleaved","clustered"]},"optionLabels":{"interleaved":"Intercalada","clustered":"Agrupada"},"defaultValue":"interleaved"}'::jsonb,'"interleaved"'::jsonb),
('practice_position',8,'1.2.1','enum',array['course','lesson','didactic_microsequence','study_unit']::text[],'{"id":"practice_position","humanField":"posicao_da_pratica","group":"practice","groupLabel":"Prática","unitLabel":"posição em relação à explicação","label":"Posição das práticas","construct":"Posição pretendida da prática em relação à explicação pertinente.","operationalization":"Orienta prática antes, depois ou antes e depois da explicação; posições declaradas são observáveis sem inferir equivalência semântica.","limitations":"A posição não demonstra recuperação, domínio ou eficácia e precisa de justificativa compatível com o repertório e o objetivo.","defaultStatus":"product_hypothesis","evidenceRefs":[],"supportedScopes":["course","lesson","didactic_microsequence","study_unit"],"valueSchema":{"type":"enum","allowedValues":["before_explanation","after_explanation","before_and_after"]},"optionLabels":{"before_explanation":"Antes da explicação","after_explanation":"Depois da explicação","before_and_after":"Antes e depois"},"defaultValue":"after_explanation"}'::jsonb,'"after_explanation"'::jsonb),
('authoring_part_microsequence_target',9,'1.2.1','integer',array['course']::text[],'{"id":"authoring_part_microsequence_target","humanField":"alvo_microssequencias_por_parte","group":"cadence","groupLabel":"Produção","unitLabel":"microssequências por parte","label":"Granularidade da parte","construct":"Tamanho contextual da parte de produção, independente da quantidade de conteúdo curricular.","operationalization":"Orienta quantas microssequências existentes uma parte de produção pretende reunir, preservando cobertura, dependências e limites de transporte.","limitations":"Uma parte é uma organização de trabalho; não é unidade curricular nem autoriza truncar material ou dividir identidades para caber.","defaultStatus":"product_hypothesis","evidenceRefs":[],"supportedScopes":["course"],"valueSchema":{"type":"integer","minimum":1,"maximum":64},"optionLabels":{},"defaultValue":1}'::jsonb,'1'::jsonb),
