do $catalog_read_and_snapshot$ declare v text; begin
  select pg_get_functiondef('public.get_owned_course_design_for_actor_v3(uuid,uuid,text,text,integer,text)'::regprocedure) into v;
  if position('''parameterCatalogVersion'',''1.2.0''' in v)=0 then raise exception 'Leitor de desenho inesperado.'; end if;
  execute replace(v,'''parameterCatalogVersion'',''1.2.0''','''parameterCatalogVersion'',''1.2.1''');
  select pg_get_functiondef('private.materialize_course_authoring_part_core_v1(uuid,uuid,uuid,bigint,bigint,jsonb,text,text)'::regprocedure) into v;
  if position('v_snapshot->>''parameterCatalogVersion''<>''1.2.0''' in v)=0 then raise exception 'Writer de aplicação inesperado.'; end if;
  -- These versions have identical identities/value domains/meaning. Historical
  -- snapshots remain literal; all existing checks of values, origin and scope stay.
  execute replace(v,'v_snapshot->>''parameterCatalogVersion''<>''1.2.0''',
    'v_snapshot->>''parameterCatalogVersion'' not in (''1.2.0'',''1.2.1'')');
end $catalog_read_and_snapshot$;
